Lemma spw_impl_one_spec : forall (R WP q px vp w i lo shi : Z) ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (jr j7 : list byte),
  rw_cells bsegs m R [CB 16 jr] -> bv_unsigned sp <= R -> R + 16 <= shi -> R mod 8 = 0 ->
  ro_cells bsegs m WP [C8 (wz px); C8 (wz q)] -> accessible m WP 16 -> WP mod 8 = 0 -> aapp WP 16 ->
  rw_cells bsegs m q (SpcHdrCells (mkSPC vp 1 w i) j7) -> accessible m q 32 -> aapp q 32 -> q mod 8 = 0 -> 0 < q ->
  0 <= px < 2^64 -> 0 <= vp < 2^64 -> 0 <= w < 2^31 -> (i = 0 \/ i = 1) ->
  (WP + 16 <= q \/ q + 32 <= WP) ->
  stk bsegs m lo (bv_unsigned sp) -> lo + ASPW_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 -> mem_inv bsegs m ->
  ACONST m -> stack0 m lo shi ->
  evt bsegs (spw_impl_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R q px vp w i lo j7 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz R) (wz WP) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_SPW_IMPL) fc None m (seg_rom bsegs)).
