Definition vec_destruct_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (V vb vcap lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (V + 8, V + 16); (sh vb, sh vb + vcap)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' V [C8 (wz vb); C8 (wz vb); C8 (wz (vb + 8 * vcap))]
    /\ SHAD m' vb (cc_shadow (8 * vcap) 0)
    /\ ACONST m'.

Lemma vec_destruct_last_spec : forall (V vb vcap lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells bsegs m V [C8 (wz vb); C8 (wz (vb + 8)); C8 (wz (vb + 8 * vcap))] -> accessible m V 24 -> V mod 8 = 0 -> aapp V 24 ->
  0 < vb -> rblock_range vb (8 * vcap) -> 8 * vcap <= 2^16 -> 0 < vcap ->
  SHAD m vb (cc_shadow (8 * vcap) 8) ->
  (V + 24 <= vb \/ vb + 8 * vcap <= V) ->
  stk bsegs m lo (bv_unsigned sp) -> lo + AANNOTATE_VEC_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 -> mem_inv bsegs m -> ACONST m ->
  evt bsegs (vec_destruct_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc V vb vcap lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz V) (wz vb) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_VEC_STATEP_DESTRUCT) fc None m (seg_rom bsegs)).
